sys_script_include.script:
var RegistrationValidatorUtils = Class.create();
RegistrationValidatorUtils.prototype = {
    initialize: function() {},

   getAvailableBases: function() {
    var user = gs.getUserID();

    // Bloqueia se usuário já tem registration que não foi rejeitada
    var regCheck = new GlideRecord("x_2060759_base_m_0_registration");
    regCheck.addEncodedQuery(
        "opened_by=" + user +
        "^baseISNOTEMPTY" +
        "^state!=4"
    );
    regCheck.setLimit(1);
    regCheck.query();

    if (regCheck.hasNext()) {
        return "sys_idISEMPTY";
    }

    // Filtra bases com capacidade disponível
    var available = [];
    var base = new GlideRecord("x_2060759_base_m_0_bases");
    base.query();

    while (base.next()) {
        var maxCap = parseInt(base.getValue("maximum_capacity"), 10);
        var occCap = parseInt(base.getValue("occupied_capacity"), 10) || 0;

        if (!isNaN(maxCap) && maxCap > 0 && occCap < maxCap) {
            available.push(base.getUniqueValue());
        }
    }

    return available.length
        ? "sys_idIN" + available.join(",")
        : "sys_idISEMPTY";
},
    type: "RegistrationValidatorUtils"
};
